// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading ensures fonts are ready before render
const { fontFamily: interFamily } = loadInter();



export type OneThirdSlideProps = Record<string, any>;

const OneThirdSlide: React.FC<OneThirdSlideProps> = ({
  alignment = "left",
  backgroundColor = "#f5f5f7",
  transparentBackground = false,
  durationInSeconds = 8,
  slideColor = "#1d1d1f",
  textColor = "#ffffff",
  bulletColor = "#0071e3",
  titleText = "Strategic Highlights",
  titleFontSize = 48,
  bullets = [
    "Comprehensive market analysis",
    "Streamlined operational workflows",
    "Enhanced customer engagement",
    "Scalable infrastructure solutions"
  ],
  bulletFontSize = 32,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Handle transparent background cleanly
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  
  const durationInFrames = durationInSeconds * fps;
  const slideWidth = width / 3;

  // Slide In Animation
  const slideIn = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.8 },
  });

  // Slide Out Animation (starts 1 second before the end)
  const slideOut = spring({
    frame: frame - (durationInFrames - 30),
    fps,
    config: { damping: 14, mass: 0.8 },
  });

  // Calculate compound progress (0 -> 1 -> 0)
  const currentSlideProgress = slideIn - slideOut;
  
  // Start 100px further out to ensure box-shadow doesn't bleed onto the screen at frame 0
  const startTranslateX = alignment === "left" ? -slideWidth - 100 : slideWidth + 100;
  
  const slideTranslateX = interpolate(
    currentSlideProgress,
    [0, 1],
    [startTranslateX, 0]
  );

  // Title Animation
  const titleSpring = spring({
    frame: frame - 15,
    fps,
    config: { damping: 12 },
  });

  const titleOpacity = interpolate(titleSpring, [0, 1], [0, 1]);
  const titleTranslateY = interpolate(titleSpring, [0, 1], [20, 0]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily, overflow: 'hidden' }}>
      <div
        style={{
          position: 'absolute',
          left: alignment === "left" ? 0 : undefined,
          right: alignment === "right" ? 0 : undefined,
          top: 0,
          bottom: 0,
          width: slideWidth,
          backgroundColor: slideColor,
          transform: `translateX(${slideTranslateX}px)`,
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'center',
          padding: `${height * 0.08}px`,
          boxShadow: alignment === "left" 
            ? '15px 0 40px rgba(0,0,0,0.15)' 
            : '-15px 0 40px rgba(0,0,0,0.15)',
          transition: 'none',
        }}
      >
        <h1
          style={{
            color: textColor,
            fontSize: titleFontSize,
            fontWeight: 700,
            margin: 0,
            marginBottom: height * 0.05,
            opacity: titleOpacity,
            transform: `translateY(${titleTranslateY}px)`,
            lineHeight: 1.2,
            transition: 'none',
          }}
        >
          {titleText}
        </h1>

        <div style={{ display: 'flex', flexDirection: 'column' }}>
          {bullets.map((bullet, i) => {
            const bulletSpring = spring({
              // Stagger each bullet's entrance slightly
              frame: frame - (25 + i * 5),
              fps,
              config: { damping: 12 },
            });

            const opacity = interpolate(bulletSpring, [0, 1], [0, 1]);
            const translateY = interpolate(bulletSpring, [0, 1], [20, 0]);

            return (
              <div
                key={i}
                style={{
                  display: 'flex',
                  flexDirection: 'row',
                  alignItems: 'flex-start',
                  opacity,
                  transform: `translateY(${translateY}px)`,
                  marginBottom: height * 0.03,
                  transition: 'none',
                }}
              >
                {/* Bullet Point Circle */}
                <div
                  style={{
                    width: width * 0.006,
                    height: width * 0.006,
                    borderRadius: '50%',
                    backgroundColor: bulletColor,
                    marginRight: width * 0.015,
                    marginTop: bulletFontSize * 0.4, // Align proportionally with text cap height
                    flexShrink: 0,
                    transition: 'none',
                  }}
                />
                
                {/* Bullet Text */}
                <div
                  style={{
                    color: textColor,
                    fontSize: bulletFontSize,
                    lineHeight: 1.5,
                    flex: 1,
                    opacity: 0.9,
                    transition: 'none',
                  }}
                >
                  {bullet}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default OneThirdSlide;